namespace ToneCustoms.ShellStudio.Core;
public sealed class WallOpeningService { public WallOpening Add(ShellProject project,SceneObject wall,float offset,float width,float height,float sill,bool door){if(wall.Type!=SceneObjectType.Wall)throw new ArgumentException("Opening target must be a wall");if(width<=0||height<=0||width>=wall.Scale.X)throw new ArgumentOutOfRangeException(nameof(width));var o=new WallOpening(wall.Id,offset,width,height,sill,door);project.WallOpenings.Add(o);return o;}public IEnumerable<WallOpening> ForWall(ShellProject p,Guid wall)=>p.WallOpenings.Where(x=>x.WallId==wall); }
